using System;
using System.IO;
using System.Linq;
using System.Text.Json;
using KotNode.Core;

static class DraftingTests
{
 static int assertions;
 static void Check(bool x,string message){assertions++;if(!x)throw new Exception(message);}
 static void Near(double a,double b,string message){Check(Math.Abs(a-b)<1e-7,message+": "+a+" != "+b);}
 static void Point(XY a,JsonElement b,string message){Near(a.X,b[0].GetDouble(),message+" x");Near(a.Y,b[1].GetDouble(),message+" y");}
 public static void Run(string fixture)
 {
  using var file=JsonDocument.Parse(File.ReadAllText(fixture));int cases=0,layouts=0;
  foreach(var c in file.RootElement.GetProperty("Cases").EnumerateArray())
  {
   var p=new SpliceParameters{PipeDiameter=c.GetProperty("D").GetDouble(),PipeThickness=c.GetProperty("T").GetDouble(),DonorDiameter=c.GetProperty("D").GetDouble(),PlateThickness=c.GetProperty("T").GetDouble(),PlateLength=c.GetProperty("L").GetDouble(),PlateCount=c.GetProperty("N").GetInt32(),ClearSpacing=c.GetProperty("Spacing").GetDouble(),WeldLeg=9};
   var mark=new NodeMark{DetailCode="1",Parameters=p};double scale=c.GetProperty("Scale").GetDouble();
   Near(Splice.Calculate(p).Angle*180/Math.PI,c.GetProperty("Angle").GetDouble(),"LISP plate angle");
   var edges=Drafting.Edges(p);var expectedEdges=c.GetProperty("Edges");Check(edges.Count==expectedEdges.GetArrayLength(),"LISP weld count");
   for(int i=0;i<edges.Count;i++){var e=edges[i];var q=expectedEdges[i];Check(e.Plate==q[0].GetInt32()&&e.Side==q[1].GetInt32(),"physical weld identity");Near(e.A.X,q[2].GetDouble(),"edge ax");Near(e.A.Y,q[3].GetDouble(),"edge ay");Near(e.B.X,q[4].GetDouble(),"edge bx");Near(e.B.Y,q[5].GetDouble(),"edge by");Near(e.C.X,q[6].GetDouble(),"edge cx");Near(e.C.Y,q[7].GetDouble(),"edge cy");Near(e.A.Distance(new XY(0,0)),p.PipeDiameter/2,"weld on pipe surface");}
   var rows=Drafting.Rows(p);var expectedRows=c.GetProperty("Rows");Check(rows.Count==expectedRows.GetArrayLength(),"LISP weld row count");
   for(int i=0;i<rows.Count;i++){Near(rows[i].Edge,expectedRows[i][0].GetDouble(),"row edge");Check(rows[i].Direction==expectedRows[i][2].GetInt32(),"row direction");Check(rows[i].Visible==(expectedRows[i][1].GetInt32()==1),"row visibility");}
   var sectors=Drafting.Sectors(p);var expectedSectors=c.GetProperty("Sectors");for(int i=0;i<sectors.Count;i++)for(int j=0;j<sectors[i].Count;j++)Point(sectors[i][j],expectedSectors[i][j],"LISP sector vertex");
   var main=Drafting.Build(mark,"main",scale);var section=Drafting.Build(mark,"section",scale);
   Check(section.Geometry.Count(q=>q.Kind=="solid"&&q.Layer=="NP_WELDS")==p.PlateCount*2,"two filled section welds per plate");
   foreach(var row in rows)
   {
    double radius=Drafting.WeldRadius(row,rows,2.5*scale,p.PlateLength),center=Drafting.WeldY(row,rows,2.5*scale,p.PlateLength);
    Near(center-row.Direction*radius,row.Edge,"cross touches actual projected edge");
    foreach(var other in rows){double gap=row.Direction*(other.Edge-row.Edge);if(gap>1e-6)Check(radius*2<gap/2,"crosses fit in gap without overlap");}
   }
   // Arrow targets are on symbols generated by the same plan, rather than on the pipe silhouette.
   foreach(var tip in main.Leaders.Single(x=>x.Key=="weld-main").Tips)Check(rows.Any(row=>Math.Abs(Drafting.WeldY(row,rows,2.5*scale,p.PlateLength)-tip.Y)<1e-7),"leader targets drawn weld row");
   var p2=KotNode.Core.Json.Copy(p);p2.WeldLeg=35;var otherRows=Drafting.Rows(p2);Check(rows.Select(r=>r.Edge).SequenceEqual(otherRows.Select(r=>r.Edge)),"weld leg does not move projected rows");
   if(c.TryGetProperty("Layouts",out var full))foreach(var layout in full.EnumerateArray())
   {
    p.ButtWeld=layout.GetProperty("Butt").GetBoolean();main=Drafting.Build(mark,"main",scale);section=Drafting.Build(mark,"section",scale);
    var actual=section.Dimensions.Concat(main.Dimensions).ToList();var expected=layout.GetProperty("Dimensions");Check(actual.Count==expected.GetArrayLength(),"full LISP dimension count");
    for(int i=0;i<actual.Count;i++)
    {
     var d=actual[i];var e=expected[i];string type=e.GetProperty("Kind").GetString();Check(d.Kind==(type=="arc_dim"?"arc":type=="angle_dim"?"angle":"aligned"),"dimension kind");var a=e.GetProperty("Args");int off=d.Kind=="aligned"?0:1;if(off==1)Point(d.Center,a[0],"dimension center");Point(d.A,a[off],"dim A");Point(d.B,a[off+1],"dim B");Point(d.Line,a[off+2],"dim line");
     if(e.GetProperty("Props").TryGetProperty("textposition",out var text))Point(d.TextAt,text,"dim text");
    }
    foreach(var e in layout.GetProperty("Leaders").EnumerateArray())
    {
     string role=e[1].GetString(),key=e[0].GetString();var actualLeader=(role=="main"?main:section).Leaders.Single(x=>x.Key==key);Point(actualLeader.Landing,e[3],"leader landing");Check(actualLeader.Tips.Count==e[2].GetArrayLength(),"leader arrow count");for(int i=0;i<actualLeader.Tips.Count;i++)Point(actualLeader.Tips[i],e[2][i],"leader target");
    }
    Point(Drafting.SectionOffset(mark,scale),layout.GetProperty("MainOffset"),"section layout");layouts++;
   }
   cases++;
  }
  var sample=new NodeMark();var enabled=Drafting.Build(sample,"main",20);sample.Parameters.FrontWelds=false;var disabled=Drafting.Build(sample,"main",20);Check(enabled.Geometry.Any(x=>x.Tag=="front-weld")&&!disabled.Geometry.Any(x=>x.Tag=="front-weld"),"independent front weld switch");
  var moved=Drafting.KeepOffset(new XY(130,240),new XY(100,200),new XY(1000,2000));Near(moved.X,1030,"manual x offset retained");Near(moved.Y,2040,"manual y offset retained");
  var movedGroup=Drafting.KeepOffset(new XY(1030,2040),new XY(1000,2000),new XY(1000,2100));Near(movedGroup.X,1030,"group MOVE is not applied twice");Near(movedGroup.Y,2140,"group MOVE preserves manual layout offset");
  var old=KotNode.Core.Json.Read<Project>(File.ReadAllText(Path.Combine(AppContext.BaseDirectory,"demo.knproject.json")));Check(old.Marks[0].Parameters.FrontWelds==null&&Drafting.Build(old.Marks[0],"main",20).Geometry.Any(x=>x.Tag=="front-weld"),"0.1 JSON defaults remain compatible");old.Validate();
  Console.WriteLine("Drafting: "+cases+" LISP geometry cases, "+layouts+" full layouts; "+assertions+" assertions passed");
  File.WriteAllText(Path.Combine(AppContext.BaseDirectory,"drafting-results.json"),JsonSerializer.Serialize(new{cases,layouts,assertions,source=file.RootElement.GetProperty("SourceSHA256").GetString(),nativeAutoCAD="not executed"}));
 }
}
